class Solution {
public:
    int maxFrequencyScore(std::vector<int>& nums, int k) {
        long long MOD = 1e9 + 7;
        auto modpow = [&](long long base, long long exp) {
            long long res = 1;
            base %= MOD;
            while (exp > 0) {
                if (exp % 2 == 1) res = (res * base) % MOD;
                base = (base * base) % MOD;
                exp /= 2;
            }
            return res;
        };

        std::unordered_map<int, int> counts;
        long long cur_score = 0;

        auto add_val = [&](int x) {
            int c = counts[x];
            if (c > 0) cur_score = (cur_score - modpow(x, c) + MOD) % MOD;
            counts[x]++;
            cur_score = (cur_score + modpow(x, c + 1)) % MOD;
        };

        auto remove_val = [&](int x) {
            int c = counts[x];
            cur_score = (cur_score - modpow(x, c) + MOD) % MOD;
            counts[x]--;
            if (counts[x] > 0) cur_score = (cur_score + modpow(x, c - 1)) % MOD;
        };

        for (int i = 0; i < k; ++i) add_val(nums[i]);
        long long ans = cur_score;
        for (size_t i = k; i < nums.size(); ++i) {
            add_val(nums[i]);
            remove_val(nums[i - k]);
            ans = std::max(ans, cur_score);
        }
        return ans;
    }
};

class Solution {
    private long MOD = 1_000_000_007L;
    public int maxFrequencyScore(int[] nums, int k) {
        java.util.Map<Integer, Integer> counts = new java.util.HashMap<>();
        long curScore = 0;
        for (int i = 0; i < k; i++) {
            int x = nums[i];
            int c = counts.getOrDefault(x, 0);
            if (c > 0) curScore = (curScore - modPow(x, c) + MOD) % MOD;
            counts.put(x, c + 1);
            curScore = (curScore + modPow(x, c + 1)) % MOD;
        }
        long ans = curScore;
        for (int i = k; i < nums.length; i++) {
            int inVal = nums[i];
            int inC = counts.getOrDefault(inVal, 0);
            if (inC > 0) curScore = (curScore - modPow(inVal, inC) + MOD) % MOD;
            counts.put(inVal, inC + 1);
            curScore = (curScore + modPow(inVal, inC + 1)) % MOD;

            int outVal = nums[i - k];
            int outC = counts.get(outVal);
            curScore = (curScore - modPow(outVal, outC) + MOD) % MOD;
            if (outC == 1) {
                counts.remove(outVal);
            } else {
                counts.put(outVal, outC - 1);
                curScore = (curScore + modPow(outVal, outC - 1)) % MOD;
            }
            ans = Math.max(ans, curScore);
        }
        return (int)ans;
    }
    private long modPow(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }
}

var maxFrequencyScore = function(nums, k) {
    const MOD = 1000000007n;
    const modPow = (base, exp) => {
        let res = 1n;
        base = BigInt(base) % MOD;
        exp = BigInt(exp);
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp /= 2n;
        }
        return res;
    };

    const counts = new Map();
    let curScore = 0n;

    const addVal = (x) => {
        const c = counts.get(x) || 0;
        if (c > 0) curScore = (curScore - modPow(x, c) + MOD) % MOD;
        counts.set(x, c + 1);
        curScore = (curScore + modPow(x, c + 1)) % MOD;
    };

    const removeVal = (x) => {
        const c = counts.get(x);
        curScore = (curScore - modPow(x, c) + MOD) % MOD;
        if (c === 1) counts.delete(x);
        else {
            counts.set(x, c - 1);
            curScore = (curScore + modPow(x, c - 1)) % MOD;
        }
    };

    for (let i = 0; i < k; i++) addVal(nums[i]);
    let ans = curScore;
    for (let i = k; i < nums.length; i++) {
        addVal(nums[i]);
        removeVal(nums[i - k]);
        if (curScore > ans) ans = curScore;
    }
    return Number(ans);
};
